const Redis = require('ioredis');
let redis;

try {
    redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });

    await new Promise((resolve, reject) => {
        redis.on('ready', resolve);
        redis.on('error', reject);
        setTimeout(() => reject(new Error('Redis connection timeout')), 6000);
    });

    console.log('[Check Ingestion] Connected to Redis.');

    // Check if ingestion.active exists
    const isActive = await redis.get('ingestion.active');

    if (isActive) {
        const ttl = await redis.ttl('ingestion.active');
        console.log(`[Check Ingestion] Ingestion is ACTIVE. Last update: ${isActive}, TTL: ${ttl}s`);
    } else {
        console.log('[Check Ingestion] Ingestion is INACTIVE (key expired or missing).');
    }

    return [{ json: { 
        ingestion_active: !!isActive,
        last_update: isActive,
        ttl_remaining: isActive ? await redis.ttl('ingestion.active') : 0
    }}];

} catch (error) {
    console.error('[Check Ingestion] Redis error:', error.message);
    // On error, assume ingestion is inactive to allow restart
    return [{ json: { 
        ingestion_active: false,
        error: error.message 
    }}];

} finally {
    if (redis) {
        await redis.quit();
        console.log('[Check Ingestion] Redis connection closed.');
    }
}

