// --- START: HEARTBEAT LOGIC ---
const Redis = require('ioredis');
let redisHeartbeat;
try {
	redisHeartbeat = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });
	await new Promise((resolve, reject) => {
		redisHeartbeat.on('ready', resolve);
		redisHeartbeat.on('error', reject);
		setTimeout(() => reject(new Error('Redis connection timeout')), 6000);
	});

	// Set ingestion.active with a 20-second TTL
	await redisHeartbeat.set('ingestion.active', new Date().toISOString(), 'EX', 20);
	console.log('[Ingestor] Set ingestion.active heartbeat with 20s TTL.');

} catch (error) {
	console.error('[Ingestor] Heartbeat Redis connection/set error:', error.message);
	// Do not fail the workflow here, just log the error
} finally {
	if (redisHeartbeat) await redisHeartbeat.quit();
}
// --- END: HEARTBEAT LOGIC ---


