let redisQueue;
const items = $input.all();
const QUEUE_KEY = 'intel:queue:pending';

const killmailsToQueue = [];

// 1. Filter and Extract
for (const item of items) {
	const killmailPackage = item.json?.package;

	// Skip if no package (zKill null response)
	if (!killmailPackage) {
		continue; 
	}

	// Check for padding
	const isPadding = killmailPackage.zkb?.labels?.includes('padding') ?? false;

	// If it's NOT padding, extract data
	if (!isPadding) {
		// UPDATED: killID is now at top level of package, not nested in killmail object
		const kill_id = killmailPackage.killID;
		const hash = killmailPackage.zkb?.hash;

		if (kill_id && hash) {
			killmailsToQueue.push(JSON.stringify({
				kill_id: kill_id,
				hash: hash
			}));
		}
	}
}

// 2. Add to Queue
if (killmailsToQueue.length === 0) {
	console.log('Batch contained 0 valid killmails (likely all padding).');
	return items; // Go to Restart Polling
}

try {
	// Use a new connection for the queue logic
	redisQueue = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });
	await redisQueue.ping();

	// Use a pipeline for high-speed insertion
	const pipe = redisQueue.pipeline();
	for (const data of killmailsToQueue) {
		pipe.rpush(QUEUE_KEY, data);
	}
	await pipe.exec();

	console.log(`Successfully queued ${killmailsToQueue.length} killmails.`);

} catch (e) {
	console.error(`Failed to add killmails to queue '${QUEUE_KEY}':`, e.message);
	throw e; // Fail the workflow so it retries
} finally {
	if (redisQueue) await redisQueue.quit();
}

// Pass all items through to the "Restart Polling" node
return items;
// --- END: EXISTING QUEUE LOGIC ---
